    if parity_flip:
        bias_order = list(reversed(bias_order))

    for dx, dy in bias_order:
        nx, ny = sx + dx, sy + dy
        if not (0 <= nx < w and 0 <= ny < h) or (nx, ny) in blocked:
            continue
        s = -10**9
